const body = $input.first().json.body;

const jobTitle = body.job_title || '';
const company = body.company || '';
const jobDescription = body.job_description || '';
const resumeText = body.resume_text || '';
const interviewType = body.interview_type || 'general'; // behavioral, technical, general
const userEmail = body.email || '';
const numQuestions = parseInt(body.num_questions) || 8;

if (!jobTitle || !company || !jobDescription) {
  return [{ json: { error: 'Missing required fields: job_title, company, job_description', valid: false } }];
}

return [{
  json: {
    jobTitle,
    company,
    jobDescription: jobDescription.slice(0, 3000),
    resumeText: resumeText.slice(0, 2000),
    interviewType,
    userEmail,
    numQuestions,
    valid: true
  }
}];

