const rawText = $input.first().json.text || $input.first().json.content?.[0]?.text || '';
const inputData = $('Validate & Extract Input').first().json;

let parsed;
try {
  const clean = rawText.replace(/```json|```/g, '').trim();
  parsed = JSON.parse(clean);
} catch (e) {
  return [{ json: { error: 'Failed to parse Claude response', raw: rawText, parseError: e.message } }];
}

parsed._meta = {
  generatedAt: new Date().toISOString(),
  userEmail: inputData.userEmail,
  jobTitle: inputData.jobTitle,
  company: inputData.company
};

return [{ json: parsed }];

const data = $input.first().json;

const questions = data.questions || [];
const gaps = data.resume_gaps || [];

function escHtml(s) {
  return String(s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');
}

const questionsHtml = questions.map((q, i) => `
  <div class="question-card">
    <div class="q-number">Q${q.id}</div>
    <div class="q-text">${escHtml(q.question)}</div>
    <div class="q-meta">
      <div class="meta-block">
        <span class="meta-label">Why they ask</span>
        <span>${escHtml(q.why_they_ask)}</span>
      </div>
      <div class="meta-block">
        <span class="meta-label">Strong answer includes</span>
        <span>${escHtml(q.strong_answer_looks_like)}</span>
      </div>
      <div class="meta-block warn">
        <span class="meta-label">⚠ Watch out for</span>
        <span>${escHtml(q.watch_out_for)}</span>
      </div>
    </div>
  </div>`).join('');

const gapsHtml = gaps.length > 0
  ? `<div class="gaps-section"><h2>Gaps to prepare for</h2><ul>${gaps.map(g => `<li>${escHtml(g)}</li>`).join('')}</ul></div>`
  : '';

const html = `<!DOCTYPE html>
<html>
<head>
  <meta charset="utf-8">
  <style>
    @import url('https://fonts.googleapis.com/css2?family=IBM+Plex+Mono:wght@400;600&family=IBM+Plex+Sans:wght@400;500;600&display=swap');
    * { box-sizing: border-box; margin: 0; padding: 0; }
    body { font-family: 'IBM Plex Sans', sans-serif; background: #f7f7f5; color: #1a1a1a; }
    .wrapper { max-width: 680px; margin: 0 auto; padding: 0; background: #fff; }
    .header { background: #0f0f0f; color: #f7f7f5; padding: 28px 36px; }
    .header h1 { font-size: 20px; font-weight: 600; letter-spacing: -0.3px; }
    .header .meta { color: #888; font-size: 13px; margin-top: 4px; font-family: 'IBM Plex Mono', monospace; }
    .context { background: #f0ede8; padding: 20px 36px; font-size: 14px; line-height: 1.65; border-bottom: 1px solid #e8e4df; }
    .context strong { font-weight: 600; }
    .gaps-section { padding: 20px 36px; background: #fff8ed; border-bottom: 1px solid #ffe0b0; }
    .gaps-section h2 { font-size: 13px; font-weight: 600; text-transform: uppercase; letter-spacing: 0.5px; color: #c07000; margin-bottom: 10px; }
    .gaps-section li { font-size: 14px; line-height: 1.6; margin-bottom: 6px; padding-left: 4px; color: #7a4800; }
    .questions { padding: 24px 36px; }
    .question-card { border: 1px solid #e8e4df; border-radius: 6px; margin-bottom: 20px; overflow: hidden; }
    .q-number { background: #0f0f0f; color: #ccc; font-family: 'IBM Plex Mono', monospace; font-size: 11px; padding: 6px 14px; }
    .q-text { font-size: 16px; font-weight: 500; padding: 14px 18px 10px; line-height: 1.5; }
    .q-meta { padding: 0 18px 16px; display: flex; flex-direction: column; gap: 10px; }
    .meta-block { font-size: 13px; line-height: 1.6; }
    .meta-label { display: block; font-weight: 600; font-size: 11px; text-transform: uppercase; letter-spacing: 0.4px; color: #888; margin-bottom: 3px; }
    .meta-block.warn { background: #fdf5ec; border-left: 3px solid #f0a030; padding: 10px 12px; border-radius: 0 4px 4px 0; }
    .tip { background: #eef6ff; border-left: 3px solid #3b82f6; padding: 16px 20px; margin: 0 36px 28px; font-size: 14px; line-height: 1.65; border-radius: 0 6px 6px 0; }
    .tip strong { color: #1d4ed8; }
    .footer { background: #0f0f0f; color: #555; font-size: 11px; padding: 16px 36px; font-family: 'IBM Plex Mono', monospace; }
  </style>
</head>
<body>
  <div class="wrapper">
    <div class="header">
      <h1>Interview Prep: ${escHtml(data.role)} @ ${escHtml(data.company)}</h1>
      <div class="meta">${escHtml(data.interview_type)} interview · ${questions.length} questions · generated ${new Date().toLocaleDateString()}</div>
    </div>
    <div class="context"><strong>What ${escHtml(data.company)} is looking for:</strong> ${escHtml(data.company_context)}</div>
    ${gapsHtml}
    <div class="questions">${questionsHtml}</div>
    <div class="tip"><strong>Closing tip:</strong> ${escHtml(data.closing_tip)}</div>
    <div class="footer">Generated by Interview Prep Coach Agent · Not affiliated with ${escHtml(data.company)}</div>
  </div>
</body>
</html>`;

return [{ json: { html, subject: `Your interview prep: ${data.role} at ${data.company}`, userEmail: data._meta?.userEmail, prepData: data } }];
